import{_ as n,o as e,c as a,a4 as i}from"./chunks/framework.B-wJupoK.js";const t="/assets/logo.4oALdv-L.webp",l="/assets/screenshot-full.NpVapJUS.webp",p="/assets/console-keys.D9jA_JTC.webp",o="/assets/github-repo.BD0lvfYw.webp",m=JSON.parse('{"title":"公测期 0 元/月！商汤 SenseNova 免费 Token 再不领就没了","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/公测期 0 元月！商汤 SenseNova 免费 Token 再不领就没了/公测期 0 元月！商汤 SenseNova 免费 Token 再不领就没了.md","filePath":"AI人工智能/公测期 0 元月！商汤 SenseNova 免费 Token 再不领就没了/公测期 0 元月！商汤 SenseNova 免费 Token 再不领就没了.md","lastUpdated":1778347334000,"__rawMarkdown":"# 公测期 0 元/月！商汤 SenseNova 免费 Token 再不领就没了\\n\\n> 原生支持文档解析、图片理解、表格识别，更有 PPT 生成、深度研究等 Skills 生态一键调用。\\n\\n![SenseNova Logo](./assets/logo.webp)\\n\\n## 引言\\n\\n随着大模型技术的快速发展，越来越多的开发者开始寻找高性价比的 AI 能力接入方案。高昂的 API 调用成本往往成为个人开发者和初创团队的首要门槛。近期，商汤科技旗下的 **日日新 SenseNova** 平台推出了公测期完全免费的 Token 计划，为开发者提供了一个零成本体验原生多模态大模型能力的绝佳机会。本文将详细介绍这一免费方案的完整内容，并提供详细的接入指南，帮助你快速上手。\\n\\n## 平台简介\\n\\n**日日新 SenseNova** 是商汤科技推出的企业级大模型服务平台，其核心理念是\\"不止折扣，更是办公生产力能力包\\"。与传统的模型折扣策略不同，SenseNova 平台聚焦于提供精选模型与富裕用量保障，让开发者在面对\\"长任务\\"时也能\\"放心跑\\"。\\n\\n平台具备三大核心优势：\\n\\n1. **原生多模智能体**：贯通理解与生成的多模态底座，既能读懂文档、图片、表格，也能生成图文并茂的高质量交付物。\\n2. **更懂企业办公需求**：从理解任务到生成最终产物形成闭环，复杂办公流程一次跑到结果，而不是只停留在给建议。\\n3. **Token 消耗立省 60%**：复杂任务下 token 消耗更可控，单位成本下的可交付产出显著提升，长链路任务也能放心跑。\\n\\n## 免费方案详情\\n\\n![日日新平台页面截图](./assets/screenshot-full.webp)\\n\\n目前，SenseNova 平台处于**公测期完全免费开放**阶段，付费档位即将上线。对于想要抢先体验的开发者来说，这是一个不可错过的窗口期。\\n\\n### Free · 公测 限时放量\\n\\n| 项目 | 详情 |\\n|------|------|\\n| **价格** | ¥0/月 |\\n| **调用频次** | 每模型 1,500 次调用 / 5 小时 |\\n| **支持模型** | SenseNova 6.7 Flash-Lite、SenseNova U1 Fast |\\n| **API Key 数量** | 最多 20 个 |\\n\\n这一免费额度对于个人开发者进行原型验证、学习研究以及中小规模的业务测试来说，已经相当充裕。每 5 小时 1,500 次的调用频次设计，也充分考虑了开发调试阶段的实际需求。\\n\\n## 支持模型介绍\\n\\n免费方案目前覆盖以下两款模型：\\n\\n### SenseNova 6.7 Flash-Lite\\n\\n一款轻量级高效模型，针对快速响应场景进行了优化，适合对延迟敏感的应用场景。\\n\\n### SenseNova U1 Fast\\n\\n商汤科技的原生多模态架构模型，具备理解生成一体化能力，原生支持 **Cowork-Skills** 体系，针对办公场景进行了特化支持。\\n\\n两款模型均支持以下特性：\\n\\n- **原生多模态架构**：理解生成一体，无需拼接多个单模态模型\\n- **Cowork-Skills 体系**：办公场景特化支持，开箱即用\\n- **快速接入**：支持 **Hermes Agent** 与 **OpenClaw** 两种接入方式\\n\\n## 接入指南\\n\\n### 获取 API Key\\n\\n首先，你需要在 SenseNova 控制台注册账号并创建 API Key。\\n\\n![SenseNova 控制台登录与注册页面](./assets/console-keys.webp)\\n\\n**注册流程如下：**\\n\\n1. 访问 [SenseNova 控制台](https://platform.sensenova.cn/login)\\n2. 支持手机号登录/注册（+86 区号，短信验证码），也支持账号密码登录\\n3. 登录后进入控制台，即可创建 API Key\\n4. 免费套餐最多支持创建 **20 个 API Key**，方便你在多个项目或环境中灵活管理\\n\\n**API 配置信息：**\\n\\n| 配置项 | 值 |\\n|--------|-----|\\n| **Base URL** | `https://token.sensenova.cn/v1` |\\n| **模型名** | `sensenova-6.7-flash-lite` |\\n| **协议** | OpenAI 兼容协议 |\\n\\n### 方式一：通过 OpenClaw 接入\\n\\nOpenClaw 是推荐的主流接入方式，提供标准化的 OpenAI 兼容接口，迁移成本低。\\n\\n**环境要求：**\\n\\n- Node.js 24（推荐）或 22.14+\\n\\n**安装步骤：**\\n\\n```bash\\n# 方式 1：通过 install.sh 安装\\ncurl -fsSL https://openclaw.ai/install.sh | bash\\n\\n# 方式 2：通过 npm 安装\\nnpm install -g openclaw@latest\\n```\\n\\n**验证安装：**\\n\\n```bash\\nopenclaw --version\\nopenclaw doctor\\n```\\n\\n**配置流程：**\\n\\n运行配置向导：\\n\\n```bash\\nopenclaw onboard --install-daemon\\n```\\n\\n按提示依次选择/输入：\\n\\n1. **Setup mode**: `QuickStart`\\n2. **Model/auth provider**: `Custom Provider`\\n3. **API Base URL**: `https://token.sensenova.cn/v1`\\n4. **API Key**: 粘贴你在控制台申请到的 API Key\\n5. **Endpoint compatibility**: `OpenAI-compatible`\\n6. **Model ID**: `sensenova-6.7-flash-lite`\\n\\n**验证 LLM 通路：**\\n\\n```bash\\nopenclaw agent --message \\"你好，自我介绍一下\\" --agent main\\n```\\n\\n如果能正常返回中文回答，说明接入成功。\\n\\n### 方式二：通过 hermes-agent 接入\\n\\nhermes-agent 由 Nous Research 维护，适合需要深度集成智能体能力的应用场景。\\n\\n**安装步骤：**\\n\\n```bash\\ncurl -fsSL https://raw.githubusercontent.com/NousResearch/hermes-agent/main/scripts/install.sh | bash\\n```\\n\\n**验证安装：**\\n\\n```bash\\nhermes --version\\nhermes doctor\\n```\\n\\n**配置方式 A：命令行配置**\\n\\n```bash\\nhermes config set model.provider custom\\nhermes config set model.base_url https://token.sensenova.cn/v1\\nhermes config set model.api_key \\"<你的 API Key>\\"\\nhermes config set model.name sensenova-6.7-flash-lite\\nhermes config set model.default custom/sensenova-6.7-flash-lite\\n```\\n\\n**配置方式 B：向导配置**\\n\\n```bash\\n# 方式 1\\nhermes setup\\n\\n# 方式 2\\nhermes model\\n```\\n\\n按向导提示选择 Custom Provider，并填入对应的 Base URL、API Key 和模型名即可。\\n\\n**验证接入：**\\n\\n启动 hermes 后，输入\\"你好\\"，如果能返回中文回答，即表示接入成功。\\n\\n### 方式三：直接 API 调用（Python）\\n\\n由于接口采用 OpenAI 兼容协议，你可以直接使用 OpenAI SDK 进行调用，无需额外的适配层。\\n\\n```python\\nfrom openai import OpenAI\\n\\nclient = OpenAI(\\n    base_url=\\"https://token.sensenova.cn/v1\\",\\n    api_key=\\"your-api-key-here\\"\\n)\\n\\nresponse = client.chat.completions.create(\\n    model=\\"sensenova-6.7-flash-lite\\",\\n    messages=[\\n        {\\"role\\": \\"system\\", \\"content\\": \\"You are a helpful assistant.\\"},\\n        {\\"role\\": \\"user\\", \\"content\\": \\"你好，请介绍一下自己\\"}\\n    ]\\n)\\nprint(response.choices[0].message.content)\\n```\\n\\n只需替换 `your-api-key-here` 为你实际申请到的 API Key，即可直接运行。\\n\\n### 加载 SenseNova-Skills\\n\\n![SenseNova Skills GitHub 仓库](./assets/github-repo.webp)\\n\\nSenseNova-Skills 是商汤科技开源的办公场景技能体系，能够大幅扩展 Agent 的能力边界。\\n\\n**仓库地址：** [https://github.com/OpenSenseNova/SenseNova-Skills](https://github.com/OpenSenseNova/SenseNova-Skills)\\n\\n**Skill 目录对应关系：**\\n\\n| 接入方式 | Skill 目录路径 |\\n|----------|----------------|\\n| OpenClaw | `~/.openclaw/skills/` |\\n| hermes-agent | `~/.hermes/skills/` |\\n\\n**手动安装步骤：**\\n\\n```bash\\n# 克隆仓库\\ngit clone https://github.com/OpenSenseNova/SenseNova-Skills.git --depth=1\\n\\n# 复制到对应目录（以 OpenClaw 为例）\\ncp -r SenseNova-Skills/skills/* ~/.openclaw/skills/\\n```\\n\\n**自动安装（推荐）：**\\n\\n你也可以直接让 Agent 帮你完成安装，在对话中输入：\\n\\n> \\"请帮我把 https://github.com/OpenSenseNova/SenseNova-Skills 安装到你的 skills 目录。\\"\\n\\n**可用 Skill 列表：**\\n\\n- **图像与可视化**：`sn-image-doctor`, `sn-image-base`, `sn-infographic`, `sn-image-imitate`, `sn-image-resume`\\n- **演示文稿（PPT）**：`sn-ppt-entry`, `sn-ppt-doctor`, `sn-ppt-creative`, `sn-ppt-standard`\\n- **数据分析**：`sn-da-excel-workflow`, `sn-da-image-caption`, `sn-da-large-file-analysis`\\n- **深度研究**：`sn-deep-research`, `sn-research-planning`, `sn-dimension-research`, `sn-research-synthesis`, `sn-research-report`, `sn-report-format-discovery`, `sn-md-to-html-report`\\n- **搜索**：`sn-search-academic`, `sn-search-code`, `sn-search-social-cn`, `sn-search-social-en`\\n\\n### 一键安装（Agent Pack）\\n\\n如果你希望更快捷地完成全套部署，可以使用官方提供的跨平台一键安装器 **Agent Pack**。\\n\\n**下载地址：** [GitHub Releases](https://github.com/OpenSenseNova/agent_pack/releases/latest)\\n\\n**支持平台：**\\n\\n| 平台 | 安装包 |\\n|------|--------|\\n| Windows (x64) | `.exe` |\\n| macOS (Universal) | `.pkg` |\\n| Linux | `.sh` |\\n\\n**特点：**\\n\\n- 安装时已预置 SenseNova-Skills，无需手动加载\\n- 安装器询问 LLM 供应商时，选择 `Custom (OpenAI-compatible)`\\n- 填入 Base URL `https://token.sensenova.cn/v1` 和你的 API Key 即可完成配置\\n\\n## 使用场景\\n\\n基于 SenseNova 平台的特性，以下场景特别适合利用免费额度进行尝试：\\n\\n### 1. 智能文档处理\\n利用原生多模态能力，实现文档理解、表格提取、图文混排内容生成等办公自动化场景。\\n\\n### 2. AI 辅助内容创作\\n结合 Cowork-Skills 体系，快速搭建能够生成图文并茂交付物的 AI 写作助手。\\n\\n### 3. 企业流程自动化\\n将复杂办公流程拆解为可执行的 Agent 任务链，从任务理解到结果输出一次完成。\\n\\n### 4. 原型验证与 MVP 开发\\n对于初创团队而言，免费额度足以支撑产品原型的完整验证周期，大幅降低早期技术验证成本。\\n\\n## 总结\\n\\n商汤科技日日新 SenseNova 平台的免费 Token 计划，为开发者提供了一个零门槛体验原生多模态大模型能力的入口。每模型每 5 小时 1,500 次的调用额度、20 个 API Key 的配置上限，以及 Hermes Agent 和 OpenClaw 双接入方案的支持，使得无论是个人学习还是企业原型验证，都能找到合适的切入点。\\n\\n本文提供了三种详细的接入方式：\\n\\n- **OpenClaw**：推荐方案，标准化 OpenAI 兼容接口\\n- **hermes-agent**：深度智能体集成方案\\n- **直接 API 调用**：最轻量的 Python SDK 方式\\n\\n同时，通过加载 SenseNova-Skills 或使用预置好 Skills 的 Agent Pack 一键安装器，你可以快速获得覆盖图像生成、PPT 制作、数据分析、深度研究、多平台搜索等场景的办公生产力能力。\\n\\n需要特别注意的是，当前免费方案为**公测期限时放量**，付费档位即将上线。建议有需求的开发者尽早申请体验，锁定这一窗口期的红利。\\n\\n---\\n\\n> **相关信息**\\n> - 官方网站：[https://www.sensenova.cn/token-plan](https://www.sensenova.cn/token-plan)\\n> - 控制台地址：[https://platform.sensenova.cn/login](https://platform.sensenova.cn/login)\\n> - GitHub 开源仓库：[https://github.com/OpenSenseNova/SenseNova-Skills](https://github.com/OpenSenseNova/SenseNova-Skills)\\n> - Agent Pack 下载：[https://github.com/OpenSenseNova/agent_pack/releases/latest](https://github.com/OpenSenseNova/agent_pack/releases/latest)\\n"}'),r={name:"AI人工智能/公测期 0 元月！商汤 SenseNova 免费 Token 再不领就没了/公测期 0 元月！商汤 SenseNova 免费 Token 再不领就没了.md"};function h(k,s,d,c,g,b){return e(),a("div",null,[...s[0]||(s[0]=[i("",102)])])}const F=n(r,[["render",h]]);export{m as __pageData,F as default};
